using namespace JerzyAudio;
// The worker is permitted to allocate; the calling audio thread is not.
thread_local bool audioGuard=false;
void* operator new(std::size_t n){if(audioGuard)throw std::bad_alloc();if(auto p=std::malloc(n?n:1))return p;throw std::bad_alloc();}
void* operator new[](std::size_t n){return ::operator new(n);}
void operator delete(void* p)noexcept{std::free(p);}void operator delete[](void* p)noexcept{std::free(p);}void operator delete(void* p,std::size_t)noexcept{std::free(p);}void operator delete[](void* p,std::size_t)noexcept{std::free(p);}
void check(bool b,const char* msg){if(!b)throw std::runtime_error(msg);}
using Audio=std::vector<std::array<float,2>>;
double energy(const Audio& a,size_t first=0){double e=0;for(size_t i=first;i<a.size();++i)e+=double(a[i][0])*a[i][0]+double(a[i][1])*a[i][1];return e;}
void wav(const std::filesystem::path& path,const Audio& a,unsigned rate=48000){std::ofstream f(path,std::ios::binary);auto u16=[&](unsigned v){for(int k=0;k<2;++k)f.put(char(v>>(8*k)));};auto u32=[&](uint32_t v){for(int k=0;k<4;++k)f.put(char(v>>(8*k)));};f.write("RIFF",4);u32(36+unsigned(a.size()*8));f.write("WAVEfmt ",8);u32(16);u16(3);u16(2);u32(rate);u32(rate*8);u16(8);u16(32);f.write("data",4);u32(unsigned(a.size()*8));for(auto v:a)for(float x:v)u32(std::bit_cast<uint32_t>(x));}
Audio render(ReverbParams p,double sr=48000,double seconds=3,int block=257,double* audioSeconds=nullptr){MXReverbModule<float> m;m.prepare(sr,&p);Audio a(size_t(sr*seconds));const auto started=std::chrono::steady_clock::now();audioGuard=true;for(size_t start=0;start<a.size();start+=block)for(size_t i=start;i<std::min(a.size(),start+block);++i){float l=i==0?1.f:0,r=l;m.process(l,r,p,l,r);check(std::isfinite(l)&&std::isfinite(r),"nonfinite module output");a[i]={l,r};}audioGuard=false;if(audioSeconds)*audioSeconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-started).count();return a;}
void convolution(){std::mt19937 rng(71);std::uniform_real_distribution<float>d(-.1f,.1f);for(size_t n:{1,63,64,65,1023,1024,1025,2047,2048,2049,4095,4096,4097,53001}){MXIRAudio ir;ir.left.resize(n);ir.right.resize(n);for(size_t i=0;i<n;++i){ir.left[i]=d(rng);ir.right[i]=d(rng);}MXPartitionedConvolver c(ir);audioGuard=true;double err=0;for(size_t i=0;i<n+2048;++i){float l=i==0?1.f:0,r=l;c.process(l,r);err=std::max({err,std::abs(double(l)-(i<n?ir.left[i]:0)),std::abs(double(r)-(i<n?ir.right[i]:0))});}audioGuard=false;check(err<2e-6,"partitioned impulse differs from IR");c.reset();for(size_t i=0;i<n+1024;++i){float l=0,r=0;c.process(l,r);check(std::abs(l)+std::abs(r)<1e-9,"convolution reset leaks history");}}
 MXIRAudio ir;ir.left.resize(2197);ir.right.resize(2197);for(size_t i=0;i<2197;++i){ir.left[i]=d(rng)*.01f;ir.right[i]=d(rng)*.01f;}MXPartitionedConvolver c(ir);std::vector<float> input(7000),inputR(7000);for(auto& x:input)x=d(rng);for(auto& x:inputR)x=d(rng);for(size_t i=0;i<input.size();++i){double expected=0;for(size_t j=0;j<ir.left.size()&&j<=i;++j)expected+=double(ir.left[j])*input[i-j];double expectedR=0;for(size_t j=0;j<ir.right.size()&&j<=i;++j)expectedR+=double(ir.right[j])*inputR[i-j];float l=input[i],r=inputR[i];c.process(l,r);check(std::abs(r-expectedR)<1e-6,"FFT right channel differs from independent direct convolution");check(std::abs(l-expected)<1e-6,"FFT dense input differs from direct convolution");}
}
double centroid(const Audio& a){double e=0,t=0;for(size_t i=0;i<a.size();++i){const double v=double(a[i][0])*a[i][0]+double(a[i][1])*a[i][1];e+=v;t+=i*v;}return t/std::max(e,1e-30)/48000;}
double highRatio(const Audio& a){double diff=0,total=0;for(size_t i=4801;i<a.size();++i){diff+=std::pow(double(a[i][0])-a[i-1][0],2);total+=double(a[i][0])*a[i][0];}return diff/std::max(total,1e-30);}
void module(const std::filesystem::path& dir){ReverbParams p;p.enable=1;p.wet=1;p.preDelay=0;p.mode=0;p.damping=0;p.early=.2;p.decay=.25;
 auto shortTail=render(p);p.decay=.9;auto longTail=render(p,48000,8);check(energy(longTail,48000)>1e-8,"FDN missing late tail");check(centroid(longTail)>centroid(shortTail)*1.5,"Decay does not extend tail");auto bright=longTail;p.damping=1;auto dark=render(p);std::cout<<"HF ratios "<<highRatio(dark)<<" / "<<highRatio(bright)<<"\n";check(highRatio(dark)<highRatio(bright)*.7,"damping fails to reduce HF");
 p.decay=.6;p.damping=.3;auto fdn=render(p);p.mode=.5;auto ir=render(p);p.mode=1;p.hybrid=.37;auto hybrid=render(p);double err=0;for(size_t i=0;i<fdn.size();++i)err=std::max({err,std::abs(double(hybrid[i][0])-(.63*fdn[i][0]+.37*ir[i][0])),std::abs(double(hybrid[i][1])-(.63*fdn[i][1]+.37*ir[i][1]))});check(err<2e-6,"HYBRID is not the bounded sum of both algorithms");
 p.mode=.5;p.preDelay=.25;auto delayed=render(p);for(size_t i=0;i<2880;++i)check(delayed[i][0]==0&&delayed[i][1]==0,"predelay emits early");for(size_t i=0;i<ir.size()-2880;++i)check(std::abs(delayed[i+2880][0]-ir[i][0])<1e-6,"predelay wrong offset");
 p.preDelay=0;p.wet=0;auto dry=render(p);check(dry[0][0]==1&&energy(dry)==2,"wet zero alters dry signal");p.enable=0;p.wet=1;dry=render(p);check(dry[0][0]==1&&energy(dry)==2,"disabled module loses input");
 p.enable=1;p.mode=1;p.wet=1;auto block1=render(p,48000,.4,1),block257=render(p,48000,.4,257);check(block1==block257,"offline and realtime block partition differ");
 for(double rate:{8000.,44100.,48000.,96000.,192000.}){p.decay=1;p.damping=1;p.lowCut=1;p.diffusion=1;p.early=1;p.width=1;p.freeze=1;auto extreme=render(p,rate,.12);for(auto x:extreme)check(std::abs(x[0])<=32&&std::abs(x[1])<=32,"unstable extreme output");}
 p=ReverbParams{};p.enable=1;p.wet=1;p.preDelay=0;p.early=0;p.diffusion=0;auto clear=render(p);p.diffusion=1;auto diffuse=render(p);check(clear!=diffuse,"diffusion has no effect");p.lowCut=1;auto cut=render(p);check(cut!=diffuse,"low cut has no effect");p.width=0;auto mono=render(p);for(auto x:mono)check(x[0]==x[1],"width zero not mono");p.width=.5;p.early=1;auto early=render(p);check(energy(early)>energy(cut),"early reflections have no effect");
 wav(dir/"FDN.wav",fdn);wav(dir/"IR.wav",ir);wav(dir/"HYBRID.wav",hybrid);wav(dir/"FDN-long.wav",longTail);wav(dir/"FDN-dark.wav",dark);
 std::ofstream report(dir/"measurements.csv");report<<"mode,sample_rate,peak,rms,energy_centroid_seconds,schroeder_T20_extrapolated_RT60_seconds,first_nonzero_sample,render_seconds,audio_seconds,cpu_percent_single_core\n";
 for(int mode=0;mode<3;++mode){p=ReverbParams{};p.enable=1;p.wet=1;p.mode=mode*.5;p.preDelay=0;double elapsed=0;auto a=render(p,48000,8,257,&elapsed);double peak=0;size_t first=a.size();std::vector<double> sch(a.size()+1);for(size_t i=a.size();i-->0;){sch[i]=sch[i+1]+double(a[i][0])*a[i][0]+double(a[i][1])*a[i][1];peak=std::max({peak,std::abs(double(a[i][0])),std::abs(double(a[i][1]))});if(std::abs(a[i][0])+std::abs(a[i][1])>1e-12)first=i;}
 std::ofstream curve(dir/("decay-mode-"+std::to_string(mode)+".csv"));curve<<"seconds,schroeder_db\n";for(size_t i=0;i<a.size();i+=480)curve<<double(i)/48000<<','<<10*std::log10(std::max(1e-30,sch[i]/sch[0]))<<'\n';size_t t5=0,t25=0;for(size_t i=0;i<a.size();++i){if(!t5&&sch[i]<sch[0]*std::pow(10.,-.5))t5=i;if(!t25&&sch[i]<sch[0]*std::pow(10.,-2.5))t25=i;}const double rt=t25>t5?3.*(t25-t5)/48000:0;report<<mode<<",48000,"<<peak<<','<<std::sqrt(sch[0]/(2*a.size()))<<','<<centroid(a)<<','<<rt<<','<<first<<','<<elapsed<<",8,"<<100*elapsed/8<<'\n';}
}
void files(const std::filesystem::path& dir){
 for(int profile=0;profile<3;++profile){auto factory=prepareMXIR(factoryMXIR(profile,48000),48000,8,true);Audio a(factory.left.size());for(size_t i=0;i<a.size();++i)a[i]={factory.left[i],factory.right[i]};wav(dir/("factory-"+std::to_string(profile)+".wav"),a);}
 // Independent mono PCM fixtures: half-scale positive and negative samples.
 for(int bits:{16,24,32}){auto path=dir/("mono-pcm"+std::to_string(bits)+".wav");std::ofstream f(path,std::ios::binary);auto put=[&](uint32_t x,int n){for(int k=0;k<n;++k)f.put(char(x>>(8*k)));};int bytes=bits/8;f.write("RIFF",4);put(36+2*bytes,4);f.write("WAVEfmt ",8);put(16,4);put(1,2);put(1,2);put(48000,4);put(48000*bytes,4);put(bytes,2);put(bits,2);f.write("data",4);put(2*bytes,4);put(uint32_t(1)<<(bits-2),bytes);put(uint32_t(3)<<(bits-2),bytes);f.close();auto decoded=loadMXIRWav(path.string());check(decoded.left==decoded.right&&decoded.left[0]==.5f&&decoded.left[1]==-.5f,"mono PCM decoder wrong");}
Audio samples(3000);samples[0]={.5f,-.25f};samples[100]={.1f,.2f};auto path=dir/"external-stereo.wav";wav(path,samples,24000);auto ir=loadMXIRWav(path.string());check(ir.left[0]==.5f&&ir.right[0]==-.25f&&ir.rate==24000,"WAV stereo decoder wrong");auto resampled=prepareMXIR(ir,48000,.05,true);check(resampled.left.size()==2400,"resample/length wrong");check(std::abs(resampled.left[200])>.08,"resampling moved impulse incorrectly");
 ReverbParams p;p.enable=1;p.wet=1;p.mode=.5;p.preDelay=0;p.external=1;p.irPath=path.string();p.normalize=0;auto a=render(p,24000,.2);check(std::abs(a[0][0]-.5)<1e-6&&std::abs(a[100][1]-.2)<1e-6,"external IR not used by module");
 MXReverbModule<float> m;m.prepare(48000);m.requestPath((dir/"does-not-exist.wav").string());p.external=1;for(int block=0;block<50;++block){for(int i=0;i<256;++i){float l=.1f,r=l;audioGuard=true;m.process(l,r,p,l,r);audioGuard=false;check(std::isfinite(l),"IR error corrupts audio");}if(m.status().state==3)break;std::this_thread::sleep_for(std::chrono::milliseconds(10));}check(m.status().state==3&&!m.status().error.empty(),"missing IR not reported");
 m.requestPath(path.string());for(int block=0;block<100;++block){for(int i=0;i<256;++i){float l=.1f,r=l;audioGuard=true;m.process(l,r,p,l,r);audioGuard=false;}if(m.status().state==2)break;std::this_thread::sleep_for(std::chrono::milliseconds(10));}check(m.status().state==2,"safe external IR swap never becomes ready");
 auto expected=prepareMXIR(ir,48000,8,false);double sumL=0,sumR=0;for(float v:expected.left)sumL+=v;for(float v:expected.right)sumR+=v;float lastL=0,lastR=0;for(int i=0;i<20000;++i){float l=.1f,r=.1f;audioGuard=true;m.process(l,r,p,l,r);audioGuard=false;lastL=l;lastR=r;}check(std::abs(lastL-.1*sumL)<1e-5&&std::abs(lastR-.1*sumR)<1e-5,"published IR bank does not drive audio after crossfade");
 std::ofstream bad(dir/"bad.wav");bad<<"not audio";bad.close();bool rejected=false;try{loadMXIRWav((dir/"bad.wav").string());}catch(...){rejected=true;}check(rejected,"invalid WAV accepted");
}
void integration(){for(int routing=0;routing<3;++routing)for(double mix:{0.,.5,1.}){MXDelayParams p;p.slot[0].enable=p.slot[1].enable=0;p.mix=mix;p.routing=routing*.5;p.reverb.enable=1;p.reverb.wet=1;p.reverb.preDelay=0;MXDelayDSP<float> dsp;dsp.prepare(48000,2,&p.reverb);float inL[257]{1},inR[257]{1},outL[257]{},outR[257]{};float* in[]={inL,inR};float* out[]={outL,outR};double peak,e=0;for(int b=0;b<200;++b){audioGuard=true;dsp.process(in,out,2,257,p,120,peak);audioGuard=false;for(int i=0;i<257;++i)e+=double(outL[i])*outL[i]+double(outR[i])*outR[i];inL[0]=inR[0]=0;}check(e>1e-6,"standalone reverb silent with delays off");p.bypass=1;p.spill=0;inL[0]=.37f;inR[0]=-.23f;dsp.process(in,out,2,257,p,120,peak);check(outL[0]==inL[0]&&outR[0]==inR[0],"global bypass loses signal");p.bypass=0;inL[0]=inR[0]=0;dsp.process(in,out,2,257,p,120,peak);for(int i=0;i<257;++i)check(outL[i]==0&&outR[i]==0,"no-trails bypass resumes stale reverb buffers");}
 ReverbParams p;p.enable=1;p.wet=.5;MXReverbModule<double> m;m.prepare(48000,&p);double previous=0,maxJump=0;for(int i=0;i<144000;++i){if(i==48000)p.mode=.5;if(i==96000)p.mode=1;double l=.1,r=.1;audioGuard=true;m.process(l,r,p,l,r);audioGuard=false;if(i%48000<2000&&i>=48000)maxJump=std::max(maxJump,std::abs(l-previous));previous=l;}check(maxJump<.02,"mode switch discontinuity");
}
void longIRBenchmark(const std::filesystem::path& dir){
 std::ofstream report(dir/"long-ir-cpu.csv");report<<"rate,ir_seconds,audio_seconds,wall_cpu_percent,process_cpu_percent,block64_p99_ms,block64_max_ms,block64_budget_ms\n";
 for(double rate:{48000.,96000.}){
  MXIRAudio ir;ir.rate=rate;ir.left.resize(size_t(rate*8));ir.right.resize(ir.left.size());for(size_t i=0;i<ir.left.size();++i)ir.left[i]=ir.right[i]=float(.001*std::exp(-double(i)/(rate*2))*std::sin(i*.319));MXPartitionedConvolver c(ir);
  // Fill the entire history before timing: short warmups undercount long-IR MACs.
  for(size_t i=0;i<ir.left.size()+2048;++i){float l=.01f,r=.01f;c.process(l,r);}
  const int blocks=int(rate*2/64);std::vector<double> times(blocks);auto started=std::chrono::steady_clock::now();const auto cpuStarted=std::clock();audioGuard=true;
  for(int b=0;b<blocks;++b){const auto bs=std::chrono::steady_clock::now();for(int i=0;i<64;++i){float l=.01f,r=.01f;c.process(l,r);check(std::isfinite(l)&&std::isfinite(r),"long IR produced NaN/Inf");}times[b]=std::chrono::duration<double>(std::chrono::steady_clock::now()-bs).count();}
  audioGuard=false;const double cpu=double(std::clock()-cpuStarted)/CLOCKS_PER_SEC,elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-started).count();std::sort(times.begin(),times.end());report<<rate<<",8,2,"<<50*elapsed<<','<<50*cpu<<','<<times[size_t(blocks*.99)]*1000<<','<<times.back()*1000<<','<<64000/rate<<'\n';
 }
}
int main(int argc,char** argv){try{std::filesystem::path dir=argc>1?argv[1]:"reverb-results";std::filesystem::create_directories(dir);convolution();std::cout<<"Exact partitioned convolution and reset passed\n";module(dir);std::cout<<"FDN, HYBRID, damping, predelay, wet/dry, rates, offline passed\n";files(dir);std::cout<<"External IR, resampling, errors, async replacement passed\n";integration();longIRBenchmark(dir);std::cout<<"Standalone routing, bypass, smoothing, audio-thread allocation guard passed\n";}catch(const std::exception& e){audioGuard=false;std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}}
